import React, { Ref } from 'react';
import type { Components } from 'react-markdown/src/ast-to-react';
import styled from 'styled-components';

import { getTextStyle } from '../../../core/utils/styles/text-styles.js';

const StyledWrapper = /* @__PURE__ */ styled('div')({
  ...getTextStyle('base'),
  '> :first-child': {
    marginTop: '0',
  },
  '> :last-child': {
    marginBottom: '0',
  },
  wordBreak: 'normal',
  overflowWrap: 'anywhere',
});

export const wrapperMappings = (
  forwardRef: Ref<HTMLDivElement>,
): Components => ({
  div: ({ className, ...props }) => {
    if (className === 'wrapper') {
      return (
        <StyledWrapper {...props} data-testid="markdown" ref={forwardRef} />
      );
    }
    return <div {...props} />;
  },
});
